func fixture(t *testing.T) (string, string) {
	t.Helper()
	root := t.TempDir()
	write(t, root, "go.mod", "module example.test/repo\n\ngo 1.27.2\n")
	write(t, root, "pkg/hand.go", "package pkg\n\nfunc hand() int { return 1 }\n")
	write(
		t,
		root,
		"pkg/gen.go",
		"// Code generated by fixture. DO NOT EDIT.\npackage pkg\nfunc gen() int { return 1 }\n",
	)
	write(
		t,
		root,
		"pkg/almost.go",
		"// Code generated by fixture. DO NOT EDIT\npackage pkg\nfunc almost() int { return 1 }\n",
	)
	write(
		t,
		root,
		"pkg/late.go",
		"package pkg\n// Code generated by fixture. DO NOT EDIT.\nfunc late() int { return 1 }\n",
	)
	return root, filepath.Join(root, "coverage.out")
}

func write(t *testing.T, root, name, data string) {
	t.Helper()
	filename := filepath.Join(root, name)
	requireCoverageNoError(t, os.MkdirAll(filepath.Dir(filename), 0o750))
	requireCoverageNoError(t, os.WriteFile(filename, []byte(data), 0o600))
}

func TestCLIAccountingAndFloors(t *testing.T) {
	root, profile := fixture(t)
	// Repeated blocks from merged test executions count once, with coverage ORed.
	write(t, root, "coverage.out", "mode: atomic\n"+
		"example.test/repo/pkg/hand.go:3.1,3.28 2 0\n"+
		"example.test/repo/pkg/hand.go:3.1,3.28 2 3\n"+
		"example.test/repo/pkg/gen.go:3.1,3.27 8 0\n"+
		"example.test/repo/pkg/almost.go:3.1,3.30 3 0\n"+
		"example.test/repo/pkg/late.go:3.1,3.28 5 0\n")
	var out, diagnostics bytes.Buffer
	args := []string{"-repo", root, "-profile", profile}
	requireCoverageNoError(t, run(args, &out, &diagnostics))
	var got report
	requireCoverageNoError(t, json.Unmarshal(out.Bytes(), &got))
	if len(got.Packages) != 1 {
		t.Fatalf("packages: %+v", got)
	}
	p := got.Packages[0]
	if p.Package != "example.test/repo/pkg" || p.Handwritten != (counts{2, 10}) || p.Generated != (counts{0, 8}) ||
		p.Unfiltered != (counts{2, 18}) {
		t.Fatalf("accounting: %+v", p)
	}
	checkFixtureFloors(t, root, args)
}

func checkFixtureFloors(t *testing.T, root string, args []string) {
	t.Helper()
	var out, diagnostics bytes.Buffer
	for _, tc := range []struct{ name, manifest, want string }{
		{"at floor", `{"packages":{"example.test/repo/pkg":20}}`, ""},
		{
			"below floor",
			`{"packages":{"example.test/repo/pkg":21}}`,
			"below floor",
		},
		{
			"new and missing",
			`{"packages":{"example.test/repo/old":0}}`,
			"untracked measured package",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			write(t, root, "floors.json", tc.manifest)
			out.Reset()
			err := run(append(args, "-floors", filepath.Join(root, "floors.json")), &out, &diagnostics)
			if tc.want == "" {
				requireCoverageNoError(t, err)
				return
			}
			if err == nil || !strings.Contains(out.String(), tc.want) {
				t.Fatalf("err=%v report=%s", err, &out)
			}
			if tc.name == "new and missing" && !strings.Contains(out.String(), "tracked package missing from profile") {
				t.Fatal(out.String())
			}
		})
	}
}

func TestRejectInvalidProfiles(t *testing.T) {
	for _, tc := range []struct{ name, profile string }{
		{"empty", ""},
		{"header only", "mode: set\n"},
		{"mode", "mode: bogus\n"},
		{"partial record", "mode: set\nexample.test/repo/pkg/hand.go:3.1,3.28 2"},
		{"no final newline", "mode: set\nexample.test/repo/pkg/hand.go:3.1,3.28 2 1"},
		{"bad record", "mode: set\nbad\n"},
		{"blank record", "mode: set\n\n"},
		{"negative", "mode: count\nexample.test/repo/pkg/hand.go:3.1,3.28 2 -1\n"},
		{"set count", "mode: set\nexample.test/repo/pkg/hand.go:3.1,3.28 2 2\n"},
		{"integer overflow", "mode: count\nexample.test/repo/pkg/hand.go:3.1,3.28 2 18446744073709551616\n"},
		{"total overflow", "mode: count\nexample.test/repo/pkg/hand.go:3.1,3.10 18446744073709551615 1\n" +
			"example.test/repo/pkg/hand.go:3.11,3.28 1 0\n"},
		{"conflicting duplicates", "mode: count\nexample.test/repo/pkg/hand.go:3.1,3.28 2 0\n" +
			"example.test/repo/pkg/hand.go:3.1,3.28 3 1\n"},
		{"outside module", "mode: set\nother/pkg/gen.go:3.1,3.27 2 1\n"},
		{"traversal", "mode: set\nexample.test/repo/../pkg/gen.go:3.1,3.27 2 1\n"},
		{"cleaned traversal", "mode: set\nexample.test/repo/pkg/../pkg/gen.go:3.1,3.27 2 1\n"},
		{"double separator", "mode: set\nexample.test/repo/pkg//gen.go:3.1,3.27 2 1\n"},
		{"absolute", "mode: set\nexample.test/repo//pkg/gen.go:3.1,3.27 2 1\n"},
		{"backslash", "mode: set\nexample.test/repo/pkg\\gen.go:3.1,3.27 2 1\n"},
		{"missing source", "mode: set\nexample.test/repo/pkg/missing.go:3.1,3.27 2 1\n"},
		{"out of bounds", "mode: set\nexample.test/repo/pkg/gen.go:99.1,99.27 2 1\n"},
		{"column bounds", "mode: set\nexample.test/repo/pkg/gen.go:3.1,3.999 2 1\n"},
		{"reverse range", "mode: set\nexample.test/repo/pkg/gen.go:3.27,3.1 2 1\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			root, profile := fixture(t)
			write(t, root, "coverage.out", tc.profile)
			var out bytes.Buffer
			if err := run([]string{"-repo", root, "-profile", profile}, &out, &out); err == nil {
				t.Fatal("accepted invalid profile")
			}
		})
	}
}

func TestRejectSourceTricks(t *testing.T) {
	for _, kind := range []string{"symlink", "nested module", "invalid Go"} {
		t.Run(kind, func(t *testing.T) {
			root, profile := fixture(t)
			switch kind {
			case "symlink":
				requireCoverageNoError(
					t,
					os.Symlink(filepath.Join(root, "pkg/gen.go"), filepath.Join(root, "pkg/trick.go")),
				)
			case "nested module":
				write(t, root, "pkg/go.mod", "module nested\n")
				write(t, root, "pkg/trick.go", "package pkg\n\nfunc trick() int { return 1 }\n")
			case "invalid Go":
				write(t, root, "pkg/trick.go", "// Code generated by fixture. DO NOT EDIT.\npackage pkg\nnot Go\n")
			}
			write(t, root, "coverage.out", "mode: set\nexample.test/repo/pkg/trick.go:3.1,3.28 2 1\n")
			if _, err := measure(profile, root); err == nil {
				t.Fatal("accepted invalid source")
			}
		})
	}
}

func TestRejectSymlinkedSourceDirectories(t *testing.T) {
	for _, outside := range []bool{false, true} {
		t.Run(fmt.Sprintf("outside=%t", outside), func(t *testing.T) {
			root, profile := fixture(t)
			target := "pkg"
			if outside {
				target = t.TempDir()
				write(t, target, "hand.go", "package pkg\n\nfunc hand() int { return 1 }\n")
			}
			requireCoverageNoError(t, os.Symlink(target, filepath.Join(root, "alias")))
			write(t, root, "coverage.out", "mode: set\nexample.test/repo/alias/hand.go:3.1,3.28 2 1\n")
			var out, diagnostics bytes.Buffer
			if err := run([]string{"-repo", root, "-profile", profile}, &out, &diagnostics); err == nil {
				t.Fatal("accepted symlinked source directory")
			}
			if out.Len() != 0 {
				t.Fatal("invalid input emitted a partial report")
			}
		})
	}
}

func TestRejectInvalidManifests(t *testing.T) {
	for i, manifest := range []string{
		`{}`, `null`, `{"packages":{}}`, `{"packages":{"p":-1}}`, `{"packages":{"p":101}}`,
		`{"packages":{"p":null}}`, `{"packages":{"p":0,"p":0}}`,
		`{"packages":{"p":0},"packages":{"q":0}}`, `{"packages":{"p":0},"extra":true}`,
		`{"packages":{"p":0}} {}`, `{"packages":{"p":"0"}}`, `{"packages":`,
	} {
		t.Run(fmt.Sprint(i), func(t *testing.T) {
			root := t.TempDir()
			write(t, root, "floors.json", manifest)
			if _, err := readFloors(filepath.Join(root, "floors.json")); err == nil {
				t.Fatalf("accepted %s", manifest)
			}
		})
	}
}

func TestGeneratedOnlyPackage(t *testing.T) {
	root, profile := fixture(t)
	write(t, root, "coverage.out", "mode: count\nexample.test/repo/pkg/gen.go:3.1,3.27 8 1\n")
	got, err := measure(profile, root)
	requireCoverageNoError(t, err)
	if got.Packages[0].Handwritten != (counts{}) {
		t.Fatal(got)
	}
	if violations := check(got.Packages, map[string]float64{"example.test/repo/pkg": 0}); len(violations) != 0 {
		t.Fatal(violations)
	}
	if violations := check(got.Packages, map[string]float64{"example.test/repo/pkg": 1}); len(violations) != 1 {
		t.Fatal(violations)
	}
}

func TestCLIEmptyFunctionRange(t *testing.T) {
	for _, tc := range []struct {
		name           string
		rangeAndCounts string
		wantError      bool
	}{
		{"empty function", "3.15,3.15 0 0", false},
		{"executed empty function", "3.15,3.15 0 1", false},
		{"positive statements", "3.15,3.15 1 0", true},
		{"reversed empty range", "3.16,3.15 0 0", true},
		{"out of bounds empty range", "3.99,3.99 0 0", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			root, profile := fixture(t)
			write(t, root, "pkg/empty.go", "package pkg\n\nfunc empty() {}\n")
			write(t, root, "coverage.out", "mode: set\nexample.test/repo/pkg/empty.go:"+tc.rangeAndCounts+"\n")
			var out, diagnostics bytes.Buffer
			err := run([]string{"-repo", root, "-profile", profile}, &out, &diagnostics)
			if tc.wantError {
				if err == nil || out.Len() != 0 {
					t.Fatalf("invalid range: err=%v report=%s", err, &out)
				}
				return
			}
			if err != nil {
				t.Fatalf("valid empty-function range rejected: %v", err)
			}
			checkEmptyReport(t, out.Bytes())
		})
	}
}

func TestCLIMappedModuleAccounting(t *testing.T) {
	root, profile := fixture(t)
	write(t, root, "third_party/fork/go.mod", "module example.test/fork/v2\n")
	write(t, root, "third_party/fork/hand.go", "package fork\n\nfunc hand() int { return 1 }\n")
	write(
		t,
		root,
		"third_party/fork/gen.go",
		"// Code generated by fixture. DO NOT EDIT.\npackage fork\nfunc gen() int { return 1 }\n",
	)
	raw := "mode: atomic\nexample.test/repo/pkg/hand.go:3.1,3.28 2 1\n" +
		"example.test/fork/v2/hand.go:3.1,3.28 3 0\n" +
		"example.test/fork/v2/gen.go:3.1,3.27 5 1\n"
	write(t, root, "coverage.out", raw)
	write(t, root, "floors.json", `{"packages":{"example.test/repo/pkg":100}}`)
	args := []string{
		"-repo",
		root,
		"-profile",
		profile,
		"-floors",
		filepath.Join(root, "floors.json"),
	}
	var out, diagnostics bytes.Buffer
	if err := run(args, &out, &diagnostics); err == nil || out.Len() != 0 {
		t.Fatalf("unmapped dependency accepted: err=%v report=%s", err, &out)
	}
	requireCoverageNoError(t, run(append(args, "-module", "example.test/fork/v2=third_party/fork"), &out, &diagnostics))
	checkMappedReport(t, out.Bytes())
	fixtureRoot, err := os.OpenRoot(root)
	requireCoverageNoError(t, err)
	defer func() {
		if err := fixtureRoot.Close(); err != nil {
			t.Error(err)
		}
	}()
	after, err := fixtureRoot.ReadFile("coverage.out")
	requireCoverageNoError(t, err)
	if string(after) != raw {
		t.Fatal("raw profile was modified")
	}
}

func TestCLIRejectInvalidModuleMappings(t *testing.T) {
	for _, mapping := range []string{
		"missing-equals", "=third_party/fork", "example.test/fork=", "example.test/fork=.",
		"example.test/fork=../fork", "example.test/fork=/tmp/fork", "example.test/fork=third_party/../third_party/fork",
		"example.test/fork=third_party\\fork", "example.test/fork=third_party//fork",
		"../fork=third_party/fork", "example.test/fork=third_party/missing",
		"example.test/wrong=third_party/fork", "example.test/fork=third_party/no-module",
		"example.test/fork=third_party/alias",
	} {
		t.Run(mapping, func(t *testing.T) {
			root, profile := fixture(t)
			write(t, root, "third_party/fork/go.mod", "module example.test/fork\n")
			write(t, root, "third_party/no-module/source.go", "package missing\n")
			requireCoverageNoError(t, os.Symlink("fork", filepath.Join(root, "third_party/alias")))
			write(t, root, "coverage.out", "mode: set\nexample.test/repo/pkg/hand.go:3.1,3.28 2 1\n")
			var out, diagnostics bytes.Buffer
			if err := run(
				[]string{"-repo", root, "-profile", profile, "-module", mapping},
				&out,
				&diagnostics,
			); err == nil ||
				out.Len() != 0 {
				t.Fatalf("invalid mapping accepted: err=%v report=%s", err, &out)
			}
		})
	}
}

func TestCLIModuleBoundaries(t *testing.T) {
	root, profile := fixture(t)
	write(t, root, "local/go.mod", "module example.test/repo/local\n")
	write(t, root, "local/hand.go", "package local\n\nfunc hand() int { return 1 }\n")
	write(t, root, "other/go.mod", "module example.test/other\n")
	write(t, root, "other/hand.go", "package other\n\nfunc hand() int { return 1 }\n")
	rootRecord := "example.test/repo/pkg/hand.go:3.1,3.28 2 1\n"
	localRecord := "example.test/repo/local/hand.go:3.1,3.28 3 1\n"
	otherRecord := "example.test/other/hand.go:3.1,3.28 5 0\n"
	args := []string{
		"-repo",
		root,
		"-profile",
		profile,
		"-module",
		"example.test/repo/local=local",
		"-module",
		"example.test/other=other",
	}
	for _, tc := range []struct {
		name, records string
		extra         []string
		wantError     bool
	}{
		{"two scopes", rootRecord + localRecord + otherRecord, nil, false},
		{"unused scope is explicit", rootRecord, nil, false},
		{"missing root measurement", localRecord, nil, true},
		{"unknown dependency", rootRecord + "example.test/unknown/a.go:3.1,3.28 1 1\n", nil, true},
		{"dependency traversal", rootRecord + "example.test/other/../pkg/hand.go:3.1,3.28 1 1\n", nil, true},
		{"missing dependency source", rootRecord + "example.test/other/missing.go:3.1,3.28 1 1\n", nil, true},
		{"invalid dependency range", rootRecord + "example.test/other/hand.go:99.1,99.28 1 1\n", nil, true},
		{"root path cannot enter nested module", rootRecord +
			"example.test/repo/other/hand.go:3.1,3.28 1 1\n", nil, true},
		{"duplicate mapping", rootRecord, []string{"-module", "example.test/other=other"}, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			write(t, root, "coverage.out", "mode: atomic\n"+tc.records)
			var out, diagnostics bytes.Buffer
			err := run(append(append([]string{}, args...), tc.extra...), &out, &diagnostics)
			if tc.wantError {
				if err == nil || out.Len() != 0 {
					t.Fatalf("err=%v report=%s", err, &out)
				}
				return
			}
			requireCoverageNoError(t, err)
			checkBoundaryReport(t, out.Bytes(), tc.name == "unused scope is explicit")
		})
	}
}

func checkMappedReport(t *testing.T, raw []byte) {
	t.Helper()
	// Decode at the public CLI seam so the contract is explicit.
	var got struct {
		Module       string          `json:"module"`
		Packages     []packageReport `json:"packages"`
		Dependencies []struct {
			Module    string          `json:"module"`
			Directory string          `json:"directory"`
			Packages  []packageReport `json:"packages"`
		} `json:"dependencies"`
	}
	requireCoverageNoError(t, json.Unmarshal(raw, &got))
	if got.Module != "example.test/repo" || len(got.Packages) != 1 || got.Packages[0].Unfiltered != (counts{2, 2}) {
		t.Fatalf("root scope: %+v", got)
	}
	if len(got.Dependencies) != 1 {
		t.Fatalf("dependency scopes: %+v", got)
	}
	dep := got.Dependencies[0]
	if dep.Module != "example.test/fork/v2" || dep.Directory != "third_party/fork" || len(dep.Packages) != 1 {
		t.Fatalf("dependency scope: %+v", dep)
	}
	p := dep.Packages[0]
	if p != (packageReport{
		Package:     "example.test/fork/v2",
		Handwritten: counts{0, 3},
		Generated:   counts{5, 5},
		Unfiltered:  counts{5, 8},
	}) {
		t.Fatalf("dependency accounting: %+v", p)
	}
}

func checkBoundaryReport(t *testing.T, raw []byte, unused bool) {
	t.Helper()
	var got report
	requireCoverageNoError(t, json.Unmarshal(raw, &got))
	if len(got.Packages) != 1 || got.Packages[0].Unfiltered != (counts{2, 2}) || len(got.Dependencies) != 2 {
		t.Fatalf("scope separation: %+v", got)
	}
	if got.Dependencies[0].Module != "example.test/other" || got.Dependencies[1].Module != "example.test/repo/local" {
		t.Fatalf("scope order: %+v", got)
	}
	checkBoundaryDependencies(t, got, unused)
}

func checkBoundaryDependencies(t *testing.T, got report, unused bool) {
	t.Helper()
	if unused {
		for _, dep := range got.Dependencies {
			if dep.Packages == nil || len(dep.Packages) != 0 {
				t.Fatalf("unused scope: %+v", dep)
			}
		}
	} else if got.Dependencies[0].Packages[0].Unfiltered != (counts{0, 5}) ||
		got.Dependencies[1].Packages[0].Unfiltered != (counts{3, 3}) {
		t.Fatalf("dependency counts: %+v", got)
	}
}

func checkEmptyReport(t *testing.T, raw []byte) {
	t.Helper()
	var got report
	requireCoverageNoError(t, json.Unmarshal(raw, &got))
	want := packageReport{Package: "example.test/repo/pkg"}
	if got.Mode != "set" || len(got.Packages) != 1 || got.Packages[0] != want {
		t.Fatalf("empty function changed statement accounting: %+v", got)
	}
}
